import 'package:cana_cabana/models/offer.dart';
import 'package:cana_cabana/models/variants.dart';
import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:flutter/foundation.dart';

// required: associates our `main.dart` with the code generated by Freezed
part 'product.freezed.dart';
// optional: Since our Person class is serializable, we must add this line.
// But if Person was not serializable, we could skip it.

@freezed
class Product with _$Product {
  const factory Product({
    required String name,
    required int id,
    required String description,
    required List<Variant> variants,
    List<Offer>? offers,
    required List<String> images,
  }) = _Product;
  factory Product.fromJson(Map<String, dynamic> json) {
    List images = json["images"];
    List<String> imageUrls = [];
    for (var element in images) {
      imageUrls.add(element["image_url"]);
    }
    List variantsJson = json["variants"];
    List<Variant> variants = [];
    for (var element in variantsJson) {
      variants.add(Variant.fromJson(element));
    }
    return Product(
      name: json["title"],
      id: json["id"],
      description: json["description"],
      images: imageUrls,
      variants: variants,
    );
  }
}
// This file is "main.dart"
